/**
 * DATABASE INDEX CLEANUP SCRIPT
 * 
 * Automatically drops duplicate indexes (e.g., column_2, column_3, etc.)
 * generated by Sequelize's `alter: true` bug on MySQL.
 */

const { Sequelize } = require('sequelize');
require('dotenv').config();

async function runCleanup() {
  console.log('🧹 Starting Database Index Cleanup...');
  
  const sequelize = new Sequelize(process.env.DB_NAME, process.env.DB_USER, process.env.DB_PASSWORD, {
    host: process.env.DB_HOST,
    port: parseInt(process.env.DB_PORT || '3306'),
    dialect: 'mysql',
    logging: false
  });

  try {
    await sequelize.authenticate();
    console.log(`📡 Connected to database: ${process.env.DB_NAME}`);

    // Get all tables in the database
    const [tables] = await sequelize.query('SHOW TABLES');
    const tableNames = tables.map(t => Object.values(t)[0]);
    console.log(`📋 Found tables: ${tableNames.join(', ')}`);

    for (const tableName of tableNames) {
      console.log(`\n🔍 Checking table: "${tableName}"`);
      
      const [indexes] = await sequelize.query(`SHOW INDEXES FROM \`${tableName}\``);
      
      // We want to identify duplicate indexes to drop.
      // E.g. key names like: sku_2, sku_3, email_2, username_2 etc.
      // Let's filter key names that match the pattern <name>_<number>
      const duplicateIndexes = [];
      const seenBases = new Set();

      for (const idx of indexes) {
        const keyName = idx.Key_name;
        if (keyName === 'PRIMARY') continue;

        // Pattern match for duplicate indexes (e.g., column_2, sku_10)
        const match = keyName.match(/^(.+)_(\d+)$/);
        if (match) {
          const baseName = match[1];
          duplicateIndexes.push({ keyName, baseName });
        }
      }

      if (duplicateIndexes.length > 0) {
        console.log(`⚠️ Found ${duplicateIndexes.length} duplicate/redundant indexes on table "${tableName}":`);
        console.table(duplicateIndexes);

        // Temporarily disable foreign keys just in case
        await sequelize.query('SET FOREIGN_KEY_CHECKS = 0;');

        for (const { keyName } of duplicateIndexes) {
          try {
            console.log(`  🔧 Dropping index "${keyName}" from table "${tableName}"...`);
            await sequelize.query(`ALTER TABLE \`${tableName}\` DROP INDEX \`${keyName}\``);
            console.log(`  ✅ Index "${keyName}" dropped.`);
          } catch (dropErr) {
            console.error(`  ❌ Failed to drop index "${keyName}":`, dropErr.message);
          }
        }

        await sequelize.query('SET FOREIGN_KEY_CHECKS = 1;');
      } else {
        console.log(`✅ No duplicate indexes found on table "${tableName}".`);
      }
    }

    console.log('\n🎉 Index cleanup completed successfully!');
    process.exit(0);

  } catch (error) {
    console.error('\n❌ Error during index cleanup:', error.message);
    process.exit(1);
  } finally {
    await sequelize.close();
  }
}

runCleanup();
